import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public void readFile(String filename) {
        // Define a base directory that serves as the root for all allowed file operations
        String basePath = "/safe/data/";

        // Construct the full path using the base directory and the user input
        Path base = Paths.get(basePath).toAbsolutePath().normalize();
        Path target = base.resolve(Paths.get(filename)).normalize();

        // Ensure the resolved path still starts with the base directory to prevent path traversal
        if (!target.startsWith(base)) {
            throw new SecurityException("Access denied: Attempted path traversal detected.");
        }

        File file = target.toFile();
        if (file.exists()) {
            System.out.println("Reading file: " + file.getAbsolutePath());
        }
    }
}
